module freq_divbyfrac #(
    parameter MUL2_DIV_CLK = 7
) (
    input               rst_n,
    input               clk,
    output              clk_div
);

reg [2:0] count;
reg clk_div_int;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        count <= 0;
        clk_div_int <= 0;
    end else begin
        case (count)
            0: begin
                count <= MUL2_DIV_CLK - 1;
                clk_div_int <= 1;
            end
            default: begin
                count <= count - 1;
                clk_div_int <= ~clk_div_int;
            end
        endcase
    end
end

assign clk_div = clk_div_int;

endmodule
